contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, uint256 approveAmount, address recipient, uint256 transferAmount) public payable {
        require(true);

        // The contract itself holds the tokens it will transfer.
        uint256 balanceBefore = c.balanceOf(address(this));

        // Rule part 1: approve sets the allowance exactly.
        c.approve(spender, approveAmount);
        uint256 allowanceAfter = c.allowance(address(this), spender);

        // Rule part 2: a transfer within balance moves exactly that amount.
        // Only perform the transfer if the test contract has enough balance.
        bool transferReverted;
        if (balanceBefore >= transferAmount) {
            try c.transfer(recipient, transferAmount) {
                transferReverted = false;
            } catch {
                transferReverted = true;
            }
        } else {
            transferReverted = true;
        }

        uint256 balanceAfter = c.balanceOf(address(this));

        // General rule: approve is exact, and a successful transfer within balance
        // decreases the sender's balance by exactly the transferred amount.
        assert(
            allowanceAfter == approveAmount &&
            (transferReverted || balanceAfter == balanceBefore - transferAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
