        if (transferCalled) {
            c.transfer(recipient, transferAmount);
        }

        uint256 balanceAfter = c.balanceOf(address(this));

        assert(
            allowanceAfter == approveAmount &&
            (!transferCalled || balanceAfter == balanceBefore - transferAmount)
        );
    }

    receive() external payable {}
}

