contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address spender, uint256 approveAmount, address recipient, uint256 transferAmount) public payable {
        require(spender != address(0), "spender zero");
        require(recipient != address(0), "recipient zero");
        require(spender != address(this), "spender is this");
        require(recipient != address(this), "recipient is this");
        require(recipient != spender, "recipient is spender");
        require(approveAmount >= transferAmount, "allowance too small");

        c.approve(spender, approveAmount);
        uint256 allowanceBefore = c.allowance(address(this), spender);
        require(allowanceBefore == approveAmount, "approve failed");

        uint256 balanceBefore = c.balanceOf(address(this));
        require(balanceBefore >= transferAmount, "insufficient balance");

        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.transferFrom.selector, address(this), spender, transferAmount));
        require(ok, "transferFrom failed");

        uint256 allowanceAfter = c.allowance(address(this), spender);
        uint256 balanceAfter = c.balanceOf(address(this));

        assert(allowanceAfter == approveAmount - transferAmount && balanceAfter == balanceBefore - transferAmount);
    }

    receive() external payable {}
}

