contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address sender, address recipient, uint256 amount) public {
        // Snapshot before the transfer.
        uint256 senderBalBefore = c.balanceOf(sender);
        uint256 recipientBalBefore = c.balanceOf(recipient);
        uint256 supplyBefore = c.totalSupply();

        // Attempt the transfer; record whether it reverted.
        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state.
        uint256 senderBalAfter = c.balanceOf(sender);
        uint256 recipientBalAfter = c.balanceOf(recipient);
        uint256 supplyAfter = c.totalSupply();

        // General rule: if the transfer succeeds, it is value-conserving and balance-exact.
        if (!reverted) {
            assert(senderBalAfter == senderBalBefore - amount);
            assert(recipientBalAfter == recipientBalBefore + amount);
            assert(supplyAfter == supplyBefore);
        }
    }

    receive() external payable {}
}

