contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0), "sender");
        require(recipient != address(0), "recipient");

        // Setup: sender must have enough balance, and msg.sender (this contract) must be approved.
        // We first give `sender` some tokens by transferring `amount` from this contract to them,
        // then approve this contract to spend `amount` from `sender`.
        // If amount is huge this may fail; use a separate approval and amount bounded by balance.
        // To keep it general, we work with `amount` and require setup success implicitly by reverts.
        // Setup call 1: mint-like transfer from this contract to sender (this contract has no tokens
        // unless it received some beforehand; instead use another approach).
        // We cannot mint directly, so we use transfer from this contract's balance only if nonzero.
        // To guarantee setup without relying on any prior mint, we can have the sender be this contract
        // itself first, but then transferFrom(sender=this, recipient, amount) requires allowance
        // from this to this - approveAndCall is not needed; approve works.
        // Simpler: sender = address(this) receiver = recipient.
        // Use parameters: sender param may be anything, but we need balance and allowance.
        // The natural general rule uses a symbolic sender that must have balance.
        // We'll restrict to sender != address(this) and perform setup by allowing the test contract
        // to be the sender. Actually to avoid requiring initial balance, we set sender to be this contract
        // after all: the contract starts with 0 tokens. So we need a way to obtain tokens. The only way
        // is via mintSynth (needs a curated pool) or transfer from someone else who has tokens - not available.
        // Therefore we test transferFrom in the case where the caller is NOT approved / sender lacks balance
        // leading to revert, and also the positive case by first transferring amount from this contract
        // to sender after obtaining tokens. But we cannot obtain tokens.
        // Alternative: the rule can be about revert conditions. We can assert that when allowance and balance
        // are zero, transferFrom reverts.
        // Given no setup, we can still check a general invariant: totalSupply is preserved by transferFrom
        // if it does not revert.
        // Let's record totalSupply and balances before the call.
        uint256 totalBefore = c.totalSupply();
        uint256 senderBalBefore = c.balanceOf(sender);
        uint256 recipientBalBefore = c.balanceOf(recipient);
        uint256 allowanceBefore = c.allowance(sender, address(this));

        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 totalAfter = c.totalSupply();
        uint256 senderBalAfter = c.balanceOf(sender);
        uint256 recipientBalAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(sender, address(this));

        // General rule: either the call reverts, or it succeeds with totalSupply unchanged,
        // sender balance decreased by amount, recipient balance increased by amount,
        // and allowance decreased (or unchanged if infinite).
        assert(
            (reverted && totalAfter == totalBefore && senderBalAfter == senderBalBefore && recipientBalAfter == recipientBalBefore && allowanceAfter == allowanceBefore)
            ||
            (!reverted
                && senderBalBefore >= amount
                && allowanceBefore >= amount
                && totalAfter == totalBefore
                && senderBalAfter == senderBalBefore - amount
                && recipientBalAfter == recipientBalBefore + amount
                && (allowanceBefore == type(uint256).max || allowanceAfter == allowanceBefore - amount)
            )
        );
    }
}

