contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mintAmt, uint256 transferAmt, uint256 burnAmt) public {
        require(mintAmt > 0);
        require(transferAmt <= mintAmt);
        require(burnAmt <= mintAmt);

        uint256 beforeSupply = c.totalSupply();
        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeTest = address(this).balance;

        bool minted;
        try c.mintSynth(address(this), mintAmt) {
            minted = true;
        } catch {
            minted = false;
        }

        if (minted) {
            assert(c.totalSupply() >= beforeSupply);
            assert(c.balanceOf(address(this)) >= beforeSender);
            assert(c.balanceOf(address(this)) == beforeSender + mintAmt);

            uint256 balBeforeTransfer = c.balanceOf(address(this));
            if (transferAmt > 0) {
                bool transferred;
                try c.transfer(address(0xdead), transferAmt) {
                    transferred = true;
                } catch {
                    transferred = false;
                }
                if (transferred) {
                    assert(c.totalSupply() == beforeSupply + mintAmt);
                    assert(c.balanceOf(address(this)) == balBeforeTransfer - transferAmt);
                }
            }

            if (burnAmt > 0) {
                bool burned;
                try c.burn(burnAmt) {
                    burned = true;
                } catch {
                    burned = false;
                }
                if (burned) {
                    assert(c.totalSupply() >= beforeSupply);
                }
            }
        }

        assert(address(this).balance >= beforeTest || address(this).balance == beforeTest);
    }

    receive() external payable {}
}

