    function run(address from, address to, uint256 amount) public {
        require(from != address(0), "!from");
        require(to != address(0), "!to");
        require(from != to, "!same");

        // set a maximum allowance from `from` to `from` (msg.sender of this call is the test contract,
        // so we call transferFrom with sender = from and msg.sender = from by making the test contract
        // call transferFrom on behalf of `from`; to do that, msg.sender for the C call must be `from`.
        // Since the test contract is the only caller, we instead approve the test contract itself and use
        // from == address(this) pattern via prank-free approach: we only can be msg.sender.
        // Therefore the owner is the test contract and the spender must be the test contract.
        // We use `address(this)` as the owner.
        address owner = address(this);
        require(from == owner, "!owner");

        c.approve(owner, type(uint256).max);

        uint256 fromBalBefore = c.balanceOf(owner);
        uint256 toBalBefore = c.balanceOf(to);
        uint256 allowBefore = c.allowance(owner, owner);

        // If the owner has insufficient balance the call reverts. To make the test robust we require enough balance.
        require(fromBalBefore >= amount, "!balance");

        c.transferFrom(owner, to, amount);

        assert(
            c.balanceOf(to) == toBalBefore + amount &&
            c.balanceOf(owner) == fromBalBefore - amount &&
            c.allowance(owner, owner) == allowBefore &&
            allowBefore == type(uint256).max
        );
    }
}

