contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 transferAmount, address recipient, uint256 burnAmount) public {
        require(recipient != address(0));

        uint256 initialTotalSupply = c.totalSupply();
        uint256 initialBalanceSender = c.balanceOf(address(this));
        uint256 initialBalanceRecipient = c.balanceOf(recipient);

        require(transferAmount <= initialBalanceSender, "insufficient balance for transfer");

        c.transfer(recipient, transferAmount);

        uint256 newSenderBalance = c.balanceOf(address(this));
        uint256 newRecipientBalance = c.balanceOf(recipient);

        assert(newSenderBalance == initialBalanceSender - transferAmount);
        assert(newRecipientBalance == initialBalanceRecipient + transferAmount);
        assert(c.totalSupply() == initialTotalSupply);

        uint256 currentBalanceSender = newSenderBalance;
        require(burnAmount <= currentBalanceSender, "insufficient balance for burn");

        c.burn(burnAmount);

        assert(c.balanceOf(address(this)) == currentBalanceSender - burnAmount);
        assert(c.totalSupply() == initialTotalSupply - burnAmount);
    }
}

