                assert(c.balanceOf(address(this)) == balBefore - transferAmount);
            } else {
                assert(allowAfterApprove >= transferAmount);
                assert(c.allowance(address(this), spender) == allowAfterApprove - transferAmount);
                assert(c.balanceOf(address(this)) == balBefore - transferAmount);
            }
        }
    }
