    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public {
        require(recipient != address(0));
        uint256 beforeSupply = c.totalSupply();
        uint256 beforeSender = c.balanceOf(address(this));
        uint256 beforeRecipient = c.balanceOf(recipient);
        bool reverted;
        try c.transfer(recipient, amount) returns (bool ok) {
            reverted = !ok;
        } catch {
            reverted = true;
        }
        uint256 afterSupply = c.totalSupply();
        uint256 afterSender = c.balanceOf(address(this));
        uint256 afterRecipient = c.balanceOf(recipient);
        assert(
            afterSupply == beforeSupply &&
            ((reverted && afterSender == beforeSender && afterRecipient == beforeRecipient) ||
             (!reverted && recipient != address(this) && afterSender == beforeSender - amount && afterRecipient == beforeRecipient + amount))
        );
    }

    receive() external payable {}
}

