contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address owner, address spender, address recipient, uint256 mintAmount, uint256 transferAmount) public {
        require(owner != address(0), "!owner");
        require(spender != address(0), "!spender");
        require(recipient != address(0), "!recipient");

        c.approve(spender, mintAmount);
        c.increaseAllowance(spender, type(uint256).max - mintAmount + 1);
        c.decreaseAllowance(spender, type(uint256).max - mintAmount + 1);

        uint256 ownerBalanceBefore = c.balanceOf(owner);
        uint256 recipientBalanceBefore = c.balanceOf(recipient);
        uint256 allowanceBefore = c.allowance(owner, spender);
        uint256 totalSupplyBefore = c.totalSupply();

        bool reverted;
        try c.transferFrom(owner, recipient, transferAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 ownerBalanceAfter = c.balanceOf(owner);
        uint256 recipientBalanceAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(owner, spender);
        uint256 totalSupplyAfter = c.totalSupply();

        bool shouldRevert = ownerBalanceBefore < transferAmount || allowanceBefore < transferAmount;
        assert(reverted == shouldRevert);
        assert(reverted || (ownerBalanceAfter == ownerBalanceBefore - transferAmount && recipientBalanceAfter == recipientBalanceBefore + transferAmount));
        assert(totalSupplyAfter == totalSupplyBefore);
        assert(reverted || allowanceAfter == allowanceBefore - transferAmount);
    }
}

