contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, uint256 amount) public {
        require(account != address(0), "account");
        require(account != address(c), "contract");

        uint256 balBefore = c.balanceOf(account);
        uint256 supplyBefore = c.totalSupply();

        uint256 allow = amount;
        c.approve(account, allow);

        _runTransferOrRevert(account, amount);

        uint256 balAfter = c.balanceOf(account);
        uint256 supplyAfter = c.totalSupply();

        assert(balAfter <= supplyAfter);

        assert(balBefore == balAfter);
    }

    function _runTransferOrRevert(address account, uint256 amount) internal {
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", address(this), account, amount)
        );
        success;
    }

    receive() external payable {}
}

