contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 amount) public payable {
        require(recipient != address(0), "recipient cannot be zero");

        // The deployer holds no initial balance, so mint the sender exactly enough to attempt the transfer.
        // Access to mintSynth requires onlyPool; we satisfy it by asking the factory for a curated pool.
        address pool = c.DEPLOYER();
        c.mintSynth(address(this), amount);

        uint256 beforeBalSender = c.balanceOf(address(this));
        uint256 beforeBalRecipient = c.balanceOf(recipient);

        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalSender = c.balanceOf(address(this));
        uint256 afterBalRecipient = c.balanceOf(recipient);

        // Rule: the transfer must have succeeded iff the sender had at least `amount` tokens.
        assert(reverted == (beforeBalSender < amount));
        // When it succeeds, the recipient's balance must increase by exactly `amount`.
        if (!reverted) {
            assert(afterBalRecipient == beforeBalRecipient + amount);
            assert(afterBalSender == beforeBalSender - amount);
        } else {
            assert(afterBalRecipient == beforeBalRecipient);
            assert(afterBalSender == beforeBalSender);
        }
    }

    receive() external payable {}
}

