    }

    function run(address member) public {
        // Seed the pool accounting for msg.sender (the InvMutTest contract) so that
        // burnSynth() has a nonzero debt and LP balance to work with.
        c.mintSynth(member, 1);

        uint256 beforeDebt = c.mapSynth_LPDebt(address(this));
        uint256 beforeLp = c.mapSynth_LPBalance(address(this));

        bool reverted;
        try c.burnSynth() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterDebt = c.mapSynth_LPDebt(address(this));
        uint256 afterLp = c.mapSynth_LPBalance(address(this));

        // General rule: burnSynth must not underflow mapSynth_LPDebt; the debt
        // must stay within the original debt and never increase, and the LP
        // balance must not increase.  If it did not revert, the debt must have
        // decreased by exactly the same amount as the LP balance (both tracked
        // in units of the burned synth).
        assert(
            afterDebt <= beforeDebt &&
            afterLp <= beforeLp &&
            afterLp + afterDebt <= beforeLp + beforeDebt &&
            (reverted || (beforeLp - afterLp) == (beforeDebt - afterDebt))
        );
    }

    receive() external payable {}
}

