contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    /// @notice General rule: after `approve`, allowance is exactly the given amount;
    /// and `transferFrom` moves exactly that amount of c's tokens from the owner to the recipient.
    function run(address spender, address recipient, uint256 amount, uint256 transferAmount) public {
        require(spender != address(0) && recipient != address(0));
        require(amount > 0);
        require(transferAmount <= amount);
        require(spender == address(this) || recipient != address(0));

        c.approve(spender, amount);

        uint256 allowanceBefore = c.allowance(address(this), spender);
        uint256 ownerBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);

        // The spender must have at least `transferAmount` of allowance; skip the
        // transfer if the approved amount is smaller (we only assert on the happy path).
        bool skipped;
        if (transferAmount <= allowanceBefore) {
            try c.transferFrom(address(this), recipient, transferAmount) {
                skipped = false;
            } catch {
                skipped = true;
            }
        } else {
            skipped = true;
        }

        uint256 allowanceAfter = c.allowance(address(this), spender);
        uint256 ownerAfter = c.balanceOf(address(this));
        uint256 recipientAfter = c.balanceOf(recipient);

        // Rule: approval is exact; when the spender uses the allowance, exactly that
        // many tokens are debited from the owner, credited to the recipient, and the
        // remaining allowance is exactly `amount - transferAmount`.
        assert(
            allowanceBefore == amount &&
            (!skipped
                ? (ownerBefore - ownerAfter == transferAmount &&
                   recipientAfter - recipientBefore == transferAmount &&
                   allowanceAfter == amount - transferAmount)
                : (ownerAfter == ownerBefore &&
                   recipientAfter == recipientBefore &&
                   allowanceAfter == allowanceBefore))
        );
    }

    receive() external payable {}
}

