contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, address recipient, uint256 mintAmount, uint256 amount) public payable {
        require(spender != address(0));
        require(recipient != address(0));
        require(amount > 0);
        require(mintAmount >= amount);

        // fund this contract with enough tokens so it can pay the spender allowance
        // mintSynth requires the caller to be a curated pool; use approveAndCall fallback? no: use transfer setup instead
        // We cannot mint directly; rely on approve/transferFrom semantics only after funding via a successful transfer is impossible without balance.
        // Instead test the allowance/balance mechanics assuming the test contract already received tokens.
        // The contract P provides no public mint; we must therefore only assert conditional behaviour when balance exists.
        // To keep the rule general and reachable, use transferFrom from a funded address is impossible from outside.
        // Fall back to a rule about approve/transferFrom reverting when balance is insufficient.

        c.approve(spender, amount);

        uint256 allowanceBefore = c.allowance(address(this), spender);
        uint256 recipientBefore = c.balanceOf(recipient);

        bool reverted;
        try c.transferFrom(address(this), recipient, amount) { reverted = false; } catch { reverted = true; }

        uint256 allowanceAfter = c.allowance(address(this), spender);
        uint256 recipientAfter = c.balanceOf(recipient);

        if (c.balanceOf(address(this)) == 0) {
            // no balance: must revert and leave allowance and recipient balance unchanged
            assert(reverted && allowanceAfter == allowanceBefore && recipientAfter == recipientBefore);
        } else {
            // with balance: transferFrom succeeds and consumes allowance
            assert(!reverted && allowanceAfter == allowanceBefore - amount && recipientAfter == recipientBefore + amount);
        }
    }
}

