contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address member, uint amount) public {
        // The onlyPool modifier requires msg.sender to be a curated pool.
        // On a fresh deployment, random addresses are not curated pools, so the
        // call must revert unless it is made by a real curated pool. We assert
        // the general rule for both the reverting and non-reverting paths.
        bool reverted;
        uint syntheticAmount;
        try c.mintSynth(member, amount) returns (uint a) {
            syntheticAmount = a;
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, the public mapping amounts must reflect
        // the minted amount (only observable via the contract's public surface).
        uint debtAfter = c.getmapAddress_LPDebt(address(this));
        uint balAfter = c.getmapAddress_LPBalance(address(this));
        uint supplyAfter = c.totalSupply();
        uint memberBalAfter = c.balanceOf(member);

        // General rule: whenever mintSynth succeeds, the synthetic token has
        // been added to the member's balance and to total supply, and the
        // caller's LP debt was increased by the requested amount.
        // When it reverts, nothing observable should have changed (the checker
        // compares fresh state, and we assert the implication form).
        assert(
            (reverted == false) ==>
                (syntheticAmount == amount &&
                 debtAfter == amount &&
                 supplyAfter >= amount &&
                 memberBalAfter >= amount)
        );
    }
}

